import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/surplus-deficit.svg",g=JSON.parse('{"title":"奥数精讲：盈亏问题初步（分配的平衡）","description":"学习如何通过“盈”与“亏”的差距来推算人数和总量，掌握盈亏问题的核心公式及其变体。","frontmatter":{"title":"奥数精讲：盈亏问题初步（分配的平衡）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["盈亏问题","逻辑推理","分配问题"],"description":"学习如何通过“盈”与“亏”的差距来推算人数和总量，掌握盈亏问题的核心公式及其变体。"},"headers":[],"relativePath":"posts/primary-math-olympiad-surplus-deficit.md","filePath":"posts/primary-math-olympiad-surplus-deficit.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-surplus-deficit.md"};function e(o,a,r,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="盈亏问题-在-多-与-少-中寻找答案" tabindex="-1">盈亏问题：在“多”与“少”中寻找答案 <a class="header-anchor" href="#盈亏问题-在-多-与-少-中寻找答案" aria-label="Permalink to &quot;盈亏问题：在“多”与“少”中寻找答案&quot;">​</a></h1><p>把一定数量的物品平均分给一定数量的人，如果每人少分，物品就有剩余（盈）；如果每人多分，物品就不足（亏）。这类通过两次分配的剩余或不足来求人数和物品总量的问题，就是<strong>盈亏问题</strong>。</p><hr><h2 id="一、-核心逻辑-总差额与分配差" tabindex="-1">一、 核心逻辑：总差额与分配差 <a class="header-anchor" href="#一、-核心逻辑-总差额与分配差" aria-label="Permalink to &quot;一、 核心逻辑：总差额与分配差&quot;">​</a></h2><p>盈亏问题的核心在于：<strong>为什么会产生总额的差距？</strong> 是因为每人分得的数量发生了变化。</p><h3 id="【基础公式】" tabindex="-1">【基础公式】 <a class="header-anchor" href="#【基础公式】" aria-label="Permalink to &quot;【基础公式】&quot;">​</a></h3><ul><li><strong>一盈一亏型：人数 = (盈 + 亏) ÷ 两次分配差</strong></li><li><strong>双盈型：人数 = (大盈 - 小盈) ÷ 两次分配差</strong></li><li><strong>双亏型：人数 = (大亏 - 小亏) ÷ 两次分配差</strong></li></ul><h3 id="【示例-1】一盈一亏" tabindex="-1">【示例 1】一盈一亏 <a class="header-anchor" href="#【示例-1】一盈一亏" aria-label="Permalink to &quot;【示例 1】一盈一亏&quot;">​</a></h3><p><strong>题目：</strong> 老师给小朋友分糖果。如果每人分 3 块，则多出 4 块；如果每人分 5 块，则少 6 块。请问有多少个小朋友？多少块糖果？</p><p><img src="'+p+'" alt="盈亏问题图解"></p><p><strong>解析过程：</strong></p><ol><li><strong>分析差距：</strong> 第二次比第一次每人多拿了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">5 - 3 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 块。</li><li><strong>总额差距：</strong> 从“多 4”变成“少 6”，中间跨越了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">4 + 6 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 块。</li><li><strong>计算人数：</strong> 这 10 块糖是因为每人多拿 2 块才耗尽并超支的。所以人数 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>1</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">= 10 \\div 2 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 人。</li><li><strong>求糖果总数：</strong><ul><li>按方案一：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mn>5</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">3 \\times 5 + 4 = 19</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span></span></span></span> 块。</li><li>按方案二：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>5</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">5 \\times 5 - 6 = 19</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span></span></span></span> 块。 <strong>结论：</strong> 5 个小朋友，19 块糖。</li></ul></li></ol><hr><h2 id="二、-引导性思考-如何区分-加-还是-减" tabindex="-1">二、 引导性思考：如何区分“加”还是“减”？ <a class="header-anchor" href="#二、-引导性思考-如何区分-加-还是-减" aria-label="Permalink to &quot;二、 引导性思考：如何区分“加”还是“减”？&quot;">​</a></h2><p>很多同学在算总差额时容易混淆是“盈+亏”还是“盈-盈”。 <strong>秘籍：</strong> 想象一个数轴。</p><ul><li>一个在“正”方向（盈），一个在“负”方向（亏），距离就是相加。</li><li>两个都在“正”方向（盈），距离就是大减小。</li><li>两个都在“负”方向（亏），距离也是大减小。</li></ul><hr><h2 id="三、-引申思考-非标准盈亏问题" tabindex="-1">三、 引申思考：非标准盈亏问题 <a class="header-anchor" href="#三、-引申思考-非标准盈亏问题" aria-label="Permalink to &quot;三、 引申思考：非标准盈亏问题&quot;">​</a></h2><p>有时候题目不会直接说“少 6 块”，而是说“有一人分不到”或者“有一人只分到 1 块”。</p><ul><li><strong>转化技巧：</strong> 统一成“少几块”。 <ul><li><em>例如：每人分 5 块，有一人分不到。这意味着“少 5 块”。</em></li><li><em>例如：每人分 5 块，有一人只分到 1 块。这意味着“少 4 块”。</em></li></ul></li></ul><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><ol><li><p><strong>基础练习：</strong> 班级分铅笔。每人 4 支多 3 支，每人 5 支少 2 支。求人数和铅笔数。 <em>提示：(3 + 2) ÷ (5 - 4)。</em></p></li><li><p><strong>进阶练习（双盈）：</strong> 同学们去植树。如果每人植 5 棵，则剩下 14 棵；如果每人植 7 棵，则剩下 4 棵。求人数和树苗数。 <em>提示：(14 - 4) ÷ (7 - 5)。</em></p></li><li><p><strong>挑战练习：</strong> 一群猴子分桃子。如果每只猴子分 10 个，则最后一只猴子只分到 2 个；如果每只猴子分 8 个，则最后剩 12 个。求猴子数。 <em>提示：分 10 个时，最后一只差 8 个（少 8）；分 8 个时，剩 12 个（盈 12）。</em></p></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>人数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>÷</mo><mn>1</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">5 \\div 1 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">÷</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 人。铅笔：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>5</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>2</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">4 \\times 5 + 3 = 23</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">3</span></span></span></span> 支。</li><li>人数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">10 \\div 2 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span> 人。树苗：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>5</mn><mo>+</mo><mn>1</mn><mn>4</mn><mo>=</mo><mn>3</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">5 \\times 5 + 14 = 39</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">9</span></span></span></span> 棵。</li><li>人数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>2</mn><mo>+</mo><mn>8</mn><mo>)</mo><mo>÷</mo><mo>(</mo><mn>1</mn><mn>0</mn><mo>−</mo><mn>8</mn><mo>)</mo><mo>=</mo><mn>2</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">(12 + 8) \\div (10 - 8) = 20 \\div 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">8</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 只猴子。桃子：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>1</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>2</mn><mo>=</mo><mn>9</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">8 \\times 10 + 12 = 92</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">2</span></span></span></span> 个。 (验证：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>×</mo><mn>1</mn><mn>0</mn><mo>−</mo><mn>8</mn><mo>=</mo><mn>9</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">10 \\times 10 - 8 = 92</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">2</span></span></span></span>。正确！)</li></ol>',26)])])}const u=s(l,[["render",e]]);export{g as __pageData,u as default};
